#!/usr/bin/env node
/* Parity harness for the browser verifier in ../../verify.html.
 *
 * Extracts the verifier library from the page's <script> (everything up to
 * the SAMPLE embed; the library ends with a module.exports hook), runs it
 * over the case corpus generated by gen_battery.py, and compares every
 * check result and the overall verdict against the Python reference
 * verifier's ground truth (truth.json).
 *
 * Usage:  python3 gen_battery.py && node run_parity.mjs
 */
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const html = fs.readFileSync(path.join(HERE, "..", "..", "verify.html"), "utf8");
const script = html.match(/<script>([\s\S]*)<\/script>/)[1];
const libSrc = script.split("const SAMPLE")[0];
const tmp = path.join(os.tmpdir(), "uibc-verify-page-lib.cjs");
fs.writeFileSync(tmp, libSrc);
const require = createRequire(import.meta.url);
const port = require(tmp);

const truth = JSON.parse(fs.readFileSync(path.join(HERE, "truth.json"), "utf8"));

function walk(dir, base, out) {
  for (const name of fs.readdirSync(dir).sort()) {
    const p = path.join(dir, name);
    const rel = base ? base + "/" + name : name;
    if (fs.statSync(p).isDirectory()) walk(p, rel, out);
    else out.set(rel, new Uint8Array(fs.readFileSync(p)));
  }
  return out;
}

let bad = 0;
for (const [name, t] of Object.entries(truth)) {
  const dirName = name.split("-")[0];
  const files = walk(path.join(HERE, "cases", dirName), "", new Map());
  const opts = {};
  if (t.opts.keyHex) opts.key = new Uint8Array(Buffer.from(t.opts.keyHex, "hex"));
  if (t.opts.pubkeyHex) opts.pubkey = new Uint8Array(Buffer.from(t.opts.pubkeyHex, "hex"));
  if (t.opts.expectHead) opts.expectHead = t.opts.expectHead;
  let rep;
  try {
    rep = await port.verifyPackage(files, opts);
  } catch (e) {
    console.log(`${name}: HARNESS-ERROR ${(e && e.stack) || e}`);
    bad++;
    continue;
  }
  const mine = { result: rep.result, checks: {} };
  for (const c of rep.checks) mine.checks[c.id] = c.result;
  const diffs = [];
  if (mine.result !== t.result) diffs.push(`overall ${mine.result} != CLI ${t.result}`);
  const ids = new Set([...Object.keys(t.checks), ...Object.keys(mine.checks)]);
  for (const id of ids) {
    if (t.checks[id] !== mine.checks[id])
      diffs.push(`${id}: port=${mine.checks[id]} CLI=${t.checks[id]}`);
  }
  if (diffs.length) {
    bad++;
    console.log(`${name}: MISMATCH -- ${diffs.join("; ")}`);
  } else {
    console.log(`${name}: OK (${rep.result})`);
  }
}
console.log(bad ? `\n${bad} mismatching runs` : "\nALL PARITY OK");
process.exit(bad ? 1 : 0);
